from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal("0")


def _money(value: Any) -> Decimal:
    """Apply legacy NVL numeric coercion and half-up cent rounding."""
    if value is None or value == "":
        return _ZERO
    return Decimal(str(value)).quantize(_CENT, rounding=ROUND_HALF_UP)


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(key=lambda index: accounts[index].get("ACCT_ID", ""))

    for index in eligible_indexes:
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")
        exposure = _ZERO

        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _money(order.get("TOT_AMT"))

        credit_limit = _money(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        release_threshold = credit_limit * Decimal(8) / Decimal(10)
        if exposure <= release_threshold and account.get("CRED_HOLD", "") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
